import type { EditorPluginCreator } from './../ricos-types/index.js';

import { backgroundColorConverter } from './color-converter.js';
import { sketchConverter } from './sketch/sketch-converter.js';
import { getSketchHighlightTextButtons } from './sketch/text-highlight-button.js';
import { tiptapSketchExtension } from './sketch/tiptap.js';
import { tiptapColorBackgroundExtension } from './tiptap-background.js';
import type { TextHighlightPluginEditorConfig } from './types.js';
import { TEXT_HIGHLIGHT_TYPE } from './types.js';

export const pluginTextHighlight: EditorPluginCreator<TextHighlightPluginEditorConfig> = (
  config = {} as TextHighlightPluginEditorConfig
) => {
  return {
    config: { ...config, type: 'textHighlight' as const },
    pmMarkConverters: [backgroundColorConverter, sketchConverter],
    pmNodeConverters: [],
    type: TEXT_HIGHLIGHT_TYPE,
    textButtons: getSketchHighlightTextButtons(config),
    tiptapExtensions: [tiptapColorBackgroundExtension, tiptapSketchExtension],
  };
};
