import { Mark_Type } from './../../ricos-types/index.js';
import type { Mark, MarkType, Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import type { EditorState, Transaction } from './../../tiptap/pm/state.js';

import type { PreviewOverride } from './range-tracking.js';

type PreviewAnimationRange = { from: number; to: number };

type PreviewBackgroundRestoreRange = {
  from: number;
  to: number;
  mark: Mark;
};

export type SketchPreviewState = ReturnType<typeof createSketchPreviewState>;

const getBackgroundMarkType = (state: EditorState): MarkType | undefined =>
  state.schema.marks[Mark_Type.COLOR_BACKGROUND];

const collectBackgroundRestoreRanges = (
  doc: ProseMirrorNode,
  markType: MarkType,
  from: number,
  to: number
): PreviewBackgroundRestoreRange[] => {
  const ranges: PreviewBackgroundRestoreRange[] = [];
  doc.nodesBetween(from, to, (node, pos) => {
    if (!node.isText) {
      return true;
    }
    const mark = node.marks.find(candidate => candidate.type === markType);
    if (mark) {
      ranges.push({
        from: Math.max(from, pos),
        to: Math.min(to, pos + node.nodeSize),
        mark,
      });
    }
    return true;
  });
  return ranges;
};

export const createSketchPreviewState = () => {
  // Module-level-style state holder (not plugin state) because other plugins'
  // `appendTransaction` runs `plugin.apply` without our preview meta and would
  // clear the request before `view.update` reads it. `animationRange` is
  // one-shot (read by the widget controller's reconcile, then cleared);
  // `override` persists until explicitly cleared.
  let animationRange: PreviewAnimationRange | null = null;
  let override: PreviewOverride | null = null;
  let backgroundRestoreRanges: PreviewBackgroundRestoreRange[] = [];

  const restoreBackgroundMarks = (tr: Transaction) => {
    const ranges = backgroundRestoreRanges;
    backgroundRestoreRanges = [];

    const docSize = tr.doc.content.size;
    for (const { from, to, mark } of ranges) {
      const safeFrom = Math.max(0, Math.min(from, docSize));
      const safeTo = Math.max(0, Math.min(to, docSize));
      if (safeFrom < safeTo) {
        tr.addMark(safeFrom, safeTo, mark);
      }
    }
  };

  const hideBackgroundMarks = (
    state: EditorState,
    tr: Transaction,
    nextOverride: PreviewOverride
  ) => {
    // Restore first so moving the hover preview re-collects from the real
    // background-mark state, not from the previously hidden subset.
    restoreBackgroundMarks(tr);

    const markType = getBackgroundMarkType(state);
    if (!markType || nextOverride.style === 'CLASSIC') {
      return;
    }

    const nextRestoreRanges = collectBackgroundRestoreRanges(
      tr.doc,
      markType,
      nextOverride.from,
      nextOverride.to
    );
    if (nextRestoreRanges.length === 0) {
      return;
    }
    backgroundRestoreRanges = nextRestoreRanges;
    tr.removeMark(nextOverride.from, nextOverride.to, markType);
  };

  return {
    getOverride: () => override,
    setOverride: (nextOverride: PreviewOverride | null) => {
      override = nextOverride;
    },
    getAnimationRange: () => animationRange,
    setAnimationRange: (range: PreviewAnimationRange | null) => {
      animationRange = range;
    },
    consumeAnimationRange: () => {
      const range = animationRange;
      animationRange = null;
      return range;
    },
    hasBackgroundRestoreRanges: () => backgroundRestoreRanges.length > 0,
    hideBackgroundMarks,
    restoreBackgroundMarks,
  };
};
