import { Plugin } from 'prosemirror-state';

import colorDataDefaults from './../ricos-schema/legacy/statics/color.defaults.json.js';
import type { ExtensionProps, MarkConfig, RicosExtension } from './../ricos-types/index.js';
import { Mark_Type } from './../ricos-types/index.js';
import { resolveDocumentColorToCss } from './../_shared/theme-color-token.js';
import { PluginKey } from './../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../tiptap/pm/view.js';
import { createRicosMarkExtension } from './../plugin-commons/index.js';

import { FOREGROUND_COLOR, FOREGROUND_COLOR_VALUE_ATTR } from './data-hooks.js';
import { OrderedSet } from './ordered-set.js';
import { createThemeColorClipboardPlugin } from './tiptap-theme-color-clipboard.js';

declare module './../tiptap/core' {
  interface Commands<ReturnType> {
    colorForeground: {
      /**
       * Set a color mark
       */
      setColor: (color: string) => ReturnType;
      /**
       * Unset a color mark
       */
      unsetColor: () => ReturnType;
      /**
       * Apply color preview as decoration
       */
      previewColor: (color: string | null) => ReturnType;
    };
  }
}

const COLOR_PREVIEW_PLUGIN_KEY = new PluginKey('colorPreview');

export const tiptapColorForegroundExtension = createRicosMarkExtension({
  type: 'mark',
  name: Mark_Type.COLOR_FOREGROUND,
  groups: [],
  reconfigure: (
    config: MarkConfig,
    _extensions: RicosExtension[],
    _props: ExtensionProps,
    settings: Record<string, unknown>
  ) => ({
    ...config,
    addOptions() {
      return {
        HTMLAttributes: {},
        ...settings,
      };
    },
  }),
  createExtensionConfig() {
    return {
      name: this.name,

      addAttributes() {
        return {
          color: { default: colorDataDefaults.foreground },
        };
      },

      parseHTML() {
        return [
          {
            tag: `span[${FOREGROUND_COLOR_VALUE_ATTR}]`,
            getAttrs: node => {
              const color = (node as HTMLElement).getAttribute(FOREGROUND_COLOR_VALUE_ATTR);
              return color ? { color } : false;
            },
          },
          {
            style: 'color',
            getAttrs: (color: string) => ({ color }),
          },
        ];
      },

      renderHTML({ HTMLAttributes: { color } }) {
        const styleColor = this.options.styleSelectionPredicate?.(color)
          ? this.options.customStyleFn?.(OrderedSet.of(color)).color
          : color;
        const resolved = resolveDocumentColorToCss(styleColor) ?? styleColor;
        return [
          'span',
          {
            'data-hook': FOREGROUND_COLOR,
            ...(color ? { [FOREGROUND_COLOR_VALUE_ATTR]: color } : {}),
            style: `color: ${resolved}; text-decoration: inherit;`,
          },
        ];
      },

      addCommands() {
        return {
          previewColor:
            color =>
            ({ tr, dispatch }) => {
              tr.setMeta(COLOR_PREVIEW_PLUGIN_KEY, color);

              dispatch?.(tr);
              return true;
            },
          setColor:
            color =>
            ({ tr, dispatch, commands }) => {
              commands.setMark(this.name, { color });

              tr.setMeta(COLOR_PREVIEW_PLUGIN_KEY, null);

              dispatch?.(tr);
              return true;
            },
          unsetColor:
            () =>
            ({ commands }) =>
              commands.setMark(this.name, { color: null }),
        };
      },

      addProseMirrorPlugins() {
        return [
          createThemeColorClipboardPlugin(),
          new Plugin({
            key: COLOR_PREVIEW_PLUGIN_KEY,

            state: {
              init() {
                return { color: null };
              },
              apply(tr) {
                const newColor = tr.getMeta(COLOR_PREVIEW_PLUGIN_KEY);
                return { color: newColor };
              },
            },

            props: {
              decorations(state) {
                const { color } = COLOR_PREVIEW_PLUGIN_KEY.getState(state);
                const { from, to } = state.selection;

                if (!color || from === to) {
                  return null;
                }

                const resolved = resolveDocumentColorToCss(color) ?? color;
                return DecorationSet.create(state.doc, [
                  Decoration.inline(from, to, {
                    style: `color: ${resolved}; text-decoration: inherit;`,
                  }),
                ]);
              },
            },
          }),
        ];
      },
    };
  },
});
