import { SketchData_Variant } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

export const DEFAULT_STYLE: SketchData_Variant = SketchData_Variant.HIGHLIGHT;
export const DEFAULT_COLOR = '$theme-color-3';
export const DEFAULT_ANIMATE = true;

export const getExplicitAnimate = (animate: boolean | undefined): boolean | undefined =>
  animate === undefined || animate === DEFAULT_ANIMATE ? undefined : animate;

export const STROKE_WIDTH = 2;
export const PADDING = 5;
export const UNDERLINE_OFFSET = 3;
export const ANIMATION_DURATION_MS = 800;
export const ITERATIONS = 2;

export const STYLE_TO_ARIA_LABEL: Partial<Record<SketchData_Variant, string>> = {
  [SketchData_Variant.UNDERLINE]: 'underlined',
  [SketchData_Variant.BOX]: 'boxed',
  [SketchData_Variant.CIRCLE]: 'circled',
  [SketchData_Variant.HIGHLIGHT]: 'highlighted',
  [SketchData_Variant.STRIKETHROUGH]: 'struck through',
  [SketchData_Variant.CROSSED_OFF]: 'crossed out',
};

// Styles drawn as a single enclosing shape. Only these merge across
// paragraph boundaries, and only between sibling paragraphs in the same
// structural container (never across list items, table cells, layout
// sections, …). Stroke styles render per line so each gets its own seed.
export const CROSS_PARAGRAPH_MERGE_STYLES = new Set<string>(['BOX', 'CIRCLE']);

// HIGHLIGHT sits BEHIND the text (layer -1); every other annotation sits
// in FRONT (layer 2). The editor host creates a local stacking context so
// negative highlight overlays stay inside the paragraph, below the browser
// caret and text, not behind the whole editor.
export const TEXT_LAYER_Z_INDEX = '1';
const BEHIND_TEXT_OVERLAY_Z_INDEX = '-1';
const IN_FRONT_OF_TEXT_OVERLAY_Z_INDEX = '2';

const isBehindTextStyle = (style: string): boolean => style === 'HIGHLIGHT';

export const getOverlayZIndex = (style: string): string =>
  isBehindTextStyle(style) ? BEHIND_TEXT_OVERLAY_Z_INDEX : IN_FRONT_OF_TEXT_OVERLAY_Z_INDEX;
