// Invariants shared by the editor (PM-driven) and viewer (DOM-driven). Both
// sides walk their own tree to compute the structural inputs, then call the
// same predicates here so grouping/merging stays consistent.

import {
  CROSS_PARAGRAPH_MERGE_STYLES,
  DEFAULT_ANIMATE,
  DEFAULT_COLOR,
  DEFAULT_STYLE,
} from './defaults.js';

type AnnotationAttrs = {
  style?: string | null;
  color?: string | null;
  animate?: boolean | null;
};

// Identity used to decide whether two adjacent annotations may share an
// overlay. Same string ⇒ matching style/color/animation ⇒ merge candidate
// (subject to the structural rules below).
export const getAnnotationSignature = (attrs: AnnotationAttrs): string => {
  const style = attrs.style || DEFAULT_STYLE;
  const color = attrs.color || DEFAULT_COLOR;
  const animate = attrs.animate ?? DEFAULT_ANIMATE;
  return `${style}|${color}|${animate}`;
};

export const isCrossParagraphMergeStyle = (style: string): boolean =>
  CROSS_PARAGRAPH_MERGE_STYLES.has(style);

// Structural merge rule applied AFTER signature match and gap check. The
// gap check is style-aware (shape styles tolerate hardBreaks, stroke styles
// don't), so the caller pre-rejects pairs whose gap contains content.
export const canMergeAdjacentByStructure = (
  style: string,
  context: { sameBlock: boolean; sameStructuralContainer: boolean }
): boolean => {
  if (context.sameBlock) {
    return true;
  }
  return isCrossParagraphMergeStyle(style) && context.sameStructuralContainer;
};
