import type { EditorState } from './../../tiptap/pm/state.js';
import type { EditorView } from './../../tiptap/pm/view.js';

import { DEFAULT_ANIMATE, DEFAULT_COLOR, DEFAULT_STYLE, getOverlayZIndex } from './defaults.js';
import type { Rect } from './draw-rough-shapes.js';
import { WIDGET_DATA_HOOK, WIDGET_KEY_ATTR, getPluginState } from './editor-decorations.js';
import type { SketchPreviewState } from './editor-preview-state.js';
import { buildRangesRects } from './editor-rects.js';
import {
  type OverlayHandle,
  createOverlayHandle,
  translateRectsToContainerSpace,
} from './overlay-handle.js';
import {
  type AnnotationGroup,
  type AnnotationRange,
  type TrackedAnnotationGroup,
  buildAnnotationGroupText,
  buildSyntheticPreviewTrackedGroups,
  isOverlayPreviewStyle,
} from './range-tracking.js';
import { stableSeedFor } from './render-sketch.js';

type OverlayEntry = {
  handle: OverlayHandle;
  widgetDom: HTMLElement;
  ranges: AnnotationRange[];
  style: string;
  color: string;
  animate: boolean;
  seed: number;
  // LCA DOM node. Changes only on structural rebuilds (Enter), so identity
  // compare detects "widget reparented" without per-keystroke churn.
  container: HTMLElement;
  // Last rects drawn, in container-local CSS pixels. Dirty-check for
  // skipping SVG rebuild when PM updated but layout didn't shift.
  lastRects: Rect[] | null;
};

type OverlayPlanEntry = Pick<OverlayEntry, 'widgetDom' | 'style' | 'color' | 'container'>;

type DesiredOverlay = {
  key: string;
  widgetDom: HTMLElement;
  trackedGroup: TrackedAnnotationGroup;
  style: string;
  color: string;
  animate: boolean;
};

type ReconcileContext = {
  docChanged: boolean;
  firstChangedPos: number;
  lastChangedPos: number;
  previewRange: { from: number; to: number } | null;
  hasPreviewRequest: boolean;
};

type ChangedDocRange = {
  firstChangedPos: number;
  lastChangedPos: number;
};

type OverlayPlan<Overlay extends OverlayPlanEntry = OverlayPlanEntry> =
  | { kind: 'keep'; entry: Overlay }
  | { kind: 'redraw'; entry: Overlay; reuseHandle: boolean }
  | { kind: 'create' };

type PlanOverlayUpdateArgs<Overlay extends OverlayPlanEntry = OverlayPlanEntry> = {
  entry?: Overlay;
  widgetDom: HTMLElement;
  currentContainer: HTMLElement;
  shouldReplayUnchangedPreview: boolean;
  nextStyle: string;
  nextColor: string;
};

type ContainerResizeRegistryOptions = {
  onResize: (containers: Set<HTMLElement>) => void;
  resizeObserverCtor?: typeof ResizeObserver;
  requestFrame?: typeof window.requestAnimationFrame;
  cancelFrame?: typeof window.cancelAnimationFrame;
  getWidth?: (container: HTMLElement) => number;
};

type ObservedContainer = {
  keys: Set<string>;
  lastWidth: number;
};

export const createSketchContainerResizeRegistry = ({
  onResize,
  resizeObserverCtor = typeof ResizeObserver !== 'undefined' ? ResizeObserver : undefined,
  requestFrame = callback => window.requestAnimationFrame(callback),
  cancelFrame = frame => window.cancelAnimationFrame(frame),
  getWidth = container => container.clientWidth,
}: ContainerResizeRegistryOptions) => {
  const observedContainers = new Map<HTMLElement, ObservedContainer>();
  const containerByKey = new Map<string, HTMLElement>();
  const pendingContainers = new Set<HTMLElement>();
  let resizeFrame: number | null = null;

  const flushResize = () => {
    resizeFrame = null;
    const resizedContainers = new Set(pendingContainers);
    pendingContainers.clear();
    onResize(resizedContainers);
  };

  const scheduleResize = () => {
    if (resizeFrame !== null) {
      return;
    }
    resizeFrame = requestFrame(flushResize);
  };

  const observer = resizeObserverCtor
    ? new resizeObserverCtor(entries => {
        for (const entry of entries) {
          const container = entry.target as HTMLElement;
          const observed = observedContainers.get(container);
          if (!observed) {
            continue;
          }
          const nextWidth = getWidth(container);
          if (nextWidth === observed.lastWidth) {
            continue;
          }
          observed.lastWidth = nextWidth;
          pendingContainers.add(container);
        }
        if (pendingContainers.size > 0) {
          scheduleResize();
        }
      })
    : null;

  const unregister = (key: string) => {
    const container = containerByKey.get(key);
    if (!container) {
      return;
    }
    containerByKey.delete(key);
    const observed = observedContainers.get(container);
    if (!observed) {
      return;
    }
    observed.keys.delete(key);
    if (observed.keys.size === 0) {
      observer?.unobserve(container);
      observedContainers.delete(container);
      pendingContainers.delete(container);
    }
  };

  const register = (key: string, container: HTMLElement) => {
    const previousContainer = containerByKey.get(key);
    if (previousContainer === container) {
      return;
    }
    unregister(key);
    containerByKey.set(key, container);
    const observed = observedContainers.get(container);
    if (observed) {
      observed.keys.add(key);
      return;
    }
    observedContainers.set(container, {
      keys: new Set([key]),
      lastWidth: getWidth(container),
    });
    observer?.observe(container);
  };

  const destroy = () => {
    if (resizeFrame !== null) {
      cancelFrame(resizeFrame);
      resizeFrame = null;
    }
    observer?.disconnect();
    observedContainers.clear();
    containerByKey.clear();
    pendingContainers.clear();
  };

  return {
    register,
    unregister,
    destroy,
  };
};

export const planOverlayUpdate = <Overlay extends OverlayPlanEntry = OverlayPlanEntry>({
  entry,
  widgetDom,
  currentContainer,
  shouldReplayUnchangedPreview,
  nextStyle,
  nextColor,
}: PlanOverlayUpdateArgs<Overlay>): OverlayPlan<Overlay> => {
  if (!entry) {
    return { kind: 'create' };
  }
  if (entry.container !== currentContainer || entry.widgetDom !== widgetDom) {
    return { kind: 'redraw', entry, reuseHandle: false };
  }
  if (shouldReplayUnchangedPreview) {
    return { kind: 'redraw', entry, reuseHandle: true };
  }
  // Matching dom+attrs ⇒ unrelated annotation; keep so it doesn't re-animate.
  if (entry.style === nextStyle && entry.color === nextColor) {
    return { kind: 'keep', entry };
  }
  return { kind: 'redraw', entry, reuseHandle: true };
};

export const doesAnnotationGroupOverlapRange = (
  group: AnnotationGroup,
  rangeToCheck: { from: number; to: number } | null
): boolean =>
  !!rangeToCheck &&
  rangeToCheck.from < rangeToCheck.to &&
  group.ranges.some(range => range.from < rangeToCheck.to && range.to > rangeToCheck.from);

const hasDisconnectedOverlay = (overlays: Map<string, OverlayEntry>): boolean => {
  for (const overlay of overlays.values()) {
    if (!overlay.widgetDom.isConnected) {
      return true;
    }
  }
  return false;
};

// Container-local rect equality: sub-pixel jitter from viewport-scroll/etc
// is filtered out; only intra-LCA text shifts matter.
const areLocalRectListsEqual = (a: Rect[], b: Rect[] | null): boolean => {
  if (!b || a.length !== b.length) {
    return false;
  }
  for (let i = 0; i < a.length; i++) {
    const next = a[i]!;
    const prev = b[i]!;
    if (next.x !== prev.x || next.y !== prev.y || next.w !== prev.w || next.h !== prev.h) {
      return false;
    }
  }
  return true;
};

// Setting an inline style — even to the same value — invalidates the style
// cache; read-then-write was measurable in per-keystroke profiles.
const syncWidgetLayer = (widgetDom: HTMLElement, style: string) => {
  const nextZIndex = getOverlayZIndex(style);
  if (widgetDom.style.zIndex !== nextZIndex) {
    widgetDom.style.zIndex = nextZIndex;
  }
};

const createEditorRoughOverlayController = (view: EditorView, previewState: SketchPreviewState) => {
  const overlays = new Map<string, OverlayEntry>();

  const dropOverlay = (key: string) => {
    const overlay = overlays.get(key);
    if (!overlay) {
      return;
    }
    containerResizeRegistry.unregister(key);
    overlay.handle.remove();
    overlays.delete(key);
  };

  const computeRects = (overlay: Pick<OverlayEntry, 'ranges' | 'style'>): DOMRect[] | null =>
    buildRangesRects(view, overlay.ranges, overlay.style);

  const drawOverlay = (
    overlay: Pick<OverlayEntry, 'handle' | 'style' | 'color' | 'seed' | 'container'>,
    rects: DOMRect[],
    animate: boolean
  ) => {
    overlay.handle.redraw({
      style: overlay.style,
      color: overlay.color,
      seed: overlay.seed,
      animate,
      rects,
      container: overlay.container,
    });
  };

  const findContainer = (widgetDom: HTMLElement): HTMLElement =>
    widgetDom.parentElement ?? view.dom;

  const redrawOverlay = (overlay: OverlayEntry) => {
    if (!overlay.widgetDom.isConnected || !overlay.container.isConnected) {
      return;
    }
    const rects = computeRects(overlay);
    if (!rects) {
      return;
    }
    const localRects = translateRectsToContainerSpace(overlay.container, rects);
    if (areLocalRectListsEqual(localRects, overlay.lastRects)) {
      return;
    }
    drawOverlay(overlay, rects, false);
    overlay.lastRects = localRects;
  };

  const containerResizeRegistry = createSketchContainerResizeRegistry({
    onResize: containers => {
      for (const overlay of overlays.values()) {
        if (containers.has(overlay.container)) {
          redrawOverlay(overlay);
        }
      }
    },
  });

  const buildTrackedGroupMap = (): Map<string, TrackedAnnotationGroup> => {
    const previewOverride = previewState.getOverride();
    const trackedGroups = getPluginState(view.state)?.trackedGroups ?? [];
    const trackedGroupByKey = new Map<string, TrackedAnnotationGroup>(
      trackedGroups.map(trackedGroup => [trackedGroup.id, trackedGroup])
    );
    if (previewOverride && isOverlayPreviewStyle(previewOverride.style)) {
      for (const synthetic of buildSyntheticPreviewTrackedGroups(view.state, previewOverride)) {
        trackedGroupByKey.set(synthetic.id, synthetic);
      }
    }
    return trackedGroupByKey;
  };

  const collectDesiredOverlays = (trackedGroupByKey: Map<string, TrackedAnnotationGroup>) => {
    const widgets = Array.from(
      view.dom.querySelectorAll<HTMLElement>(`[data-hook="${WIDGET_DATA_HOOK}"]`)
    );
    const presentKeys = new Set<string>();
    const desiredOverlays: DesiredOverlay[] = [];

    for (const widgetDom of widgets) {
      const key = widgetDom.getAttribute(WIDGET_KEY_ATTR);
      const trackedGroup = key ? trackedGroupByKey.get(key) : undefined;
      if (!key || !trackedGroup) {
        continue;
      }

      presentKeys.add(key);
      const style = trackedGroup.mark.attrs?.style || DEFAULT_STYLE;
      const color = trackedGroup.mark.attrs?.color || DEFAULT_COLOR;
      const animate = trackedGroup.mark.attrs?.animate ?? DEFAULT_ANIMATE;
      desiredOverlays.push({ key, widgetDom, trackedGroup, style, color, animate });
    }

    return { desiredOverlays, presentKeys };
  };

  const shouldMeasureKeptOverlay = (
    trackedGroup: TrackedAnnotationGroup,
    context: ReconcileContext
  ) =>
    context.docChanged &&
    trackedGroup.wrapTo >= context.firstChangedPos &&
    trackedGroup.lcaStart <= context.lastChangedPos;

  const syncKeptOverlay = (
    overlay: OverlayEntry,
    desiredOverlay: DesiredOverlay,
    context: ReconcileContext
  ) => {
    const { trackedGroup, style, color, animate } = desiredOverlay;

    overlay.ranges = [...trackedGroup.ranges];
    overlay.style = style;
    overlay.color = color;
    overlay.animate = animate;
    if (!shouldMeasureKeptOverlay(trackedGroup, context)) {
      return;
    }
    const rects = computeRects(overlay);
    if (!rects) {
      return;
    }
    const container = overlay.container;
    const localRects = translateRectsToContainerSpace(container, rects);
    if (areLocalRectListsEqual(localRects, overlay.lastRects)) {
      return;
    }
    drawOverlay(overlay, rects, false);
    overlay.lastRects = localRects;
  };

  const replaceOverlay = (
    desiredOverlay: DesiredOverlay,
    existing: OverlayEntry | undefined,
    context: ReconcileContext,
    reuseHandle: boolean
  ) => {
    const { key, widgetDom, trackedGroup, style, color, animate } = desiredOverlay;
    const { previewRange, hasPreviewRequest } = context;

    const seed = stableSeedFor(buildAnnotationGroupText(view.state.doc, trackedGroup));
    let handle: OverlayHandle;
    if (reuseHandle && existing) {
      handle = existing.handle;
    } else {
      if (existing) {
        dropOverlay(key);
      }
      handle = createOverlayHandle(widgetDom);
    }
    const container = findContainer(widgetDom);
    const replacementOverlay: OverlayEntry = {
      handle,
      widgetDom,
      ranges: [...trackedGroup.ranges],
      style,
      color,
      animate,
      seed,
      container,
      lastRects: null,
    };
    overlays.set(key, replacementOverlay);
    containerResizeRegistry.register(key, container);

    const animateThisDraw =
      animate && hasPreviewRequest && doesAnnotationGroupOverlapRange(trackedGroup, previewRange);
    const drawRects = computeRects(replacementOverlay) ?? [];
    drawOverlay(replacementOverlay, drawRects, animateThisDraw);
    replacementOverlay.lastRects =
      drawRects.length === 0 ? [] : translateRectsToContainerSpace(container, drawRects);
  };

  const applyOverlayPlan = (
    desiredOverlay: DesiredOverlay,
    plan: OverlayPlan<OverlayEntry>,
    context: ReconcileContext
  ) => {
    switch (plan.kind) {
      case 'keep':
        syncKeptOverlay(plan.entry, desiredOverlay, context);
        return;
      case 'redraw':
        replaceOverlay(desiredOverlay, plan.entry, context, plan.reuseHandle);
        return;
      case 'create':
        replaceOverlay(desiredOverlay, undefined, context, false);
    }
  };

  const syncOrCreateOverlays = (desiredOverlays: DesiredOverlay[], context: ReconcileContext) => {
    for (const desiredOverlay of desiredOverlays) {
      const { key, widgetDom, trackedGroup, style, color } = desiredOverlay;
      const existing = overlays.get(key);
      const currentContainer = findContainer(widgetDom);
      const shouldReplayUnchangedPreview =
        context.hasPreviewRequest &&
        !!existing &&
        existing.widgetDom === widgetDom &&
        doesAnnotationGroupOverlapRange(trackedGroup, context.previewRange);
      const plan = planOverlayUpdate<OverlayEntry>({
        entry: existing,
        widgetDom,
        currentContainer,
        shouldReplayUnchangedPreview,
        nextStyle: style,
        nextColor: color,
      });

      syncWidgetLayer(widgetDom, style);
      applyOverlayPlan(desiredOverlay, plan, context);
    }
  };

  const consumePreviewAnimationRequest = (hasPreviewRequest: boolean) => {
    if (hasPreviewRequest) {
      previewState.consumeAnimationRange();
    }
  };

  const dropStaleOverlays = (presentKeys: Set<string>) => {
    for (const key of Array.from(overlays.keys())) {
      if (!presentKeys.has(key)) {
        dropOverlay(key);
      }
    }
  };

  const hasDocChanged = (currentView: EditorView, prevState: EditorState) =>
    currentView.state.doc !== prevState.doc;

  const shouldReconcileOverlays = (currentView: EditorView, prevState: EditorState): boolean => {
    const docChanged = hasDocChanged(currentView, prevState);
    const decorationsChanged =
      getPluginState(currentView.state)?.decorations !== getPluginState(prevState)?.decorations;
    // Other plugins' decoration changes can collaterally destroy our widget
    // DOM (PM's `ViewTreeUpdater.destroyBetween`). PM re-creates an empty
    // div at the same position; without this check it stays empty.
    const overlaysRemounted = hasDisconnectedOverlay(overlays);
    return (
      docChanged || decorationsChanged || !!previewState.getAnimationRange() || overlaysRemounted
    );
  };

  const getChangedDocRange = (
    currentView: EditorView,
    prevState: EditorState,
    docChanged: boolean
  ): ChangedDocRange => {
    if (!docChanged) {
      return {
        firstChangedPos: Number.NEGATIVE_INFINITY,
        lastChangedPos: Number.POSITIVE_INFINITY,
      };
    }
    return {
      firstChangedPos:
        prevState.doc.content.findDiffStart(currentView.state.doc.content) ??
        Number.NEGATIVE_INFINITY,
      lastChangedPos:
        prevState.doc.content.findDiffEnd(currentView.state.doc.content)?.b ??
        Number.POSITIVE_INFINITY,
    };
  };

  const reconcileOverlays = (
    docChanged = false,
    firstChangedPos: number = Number.NEGATIVE_INFINITY,
    lastChangedPos: number = Number.POSITIVE_INFINITY
  ) => {
    const previewRange = previewState.getAnimationRange();
    const context: ReconcileContext = {
      docChanged,
      firstChangedPos,
      lastChangedPos,
      previewRange,
      hasPreviewRequest: !!previewRange,
    };
    const trackedGroupByKey = buildTrackedGroupMap();
    const { desiredOverlays, presentKeys } = collectDesiredOverlays(trackedGroupByKey);

    syncOrCreateOverlays(desiredOverlays, context);
    consumePreviewAnimationRequest(context.hasPreviewRequest);
    dropStaleOverlays(presentKeys);
  };

  let initialReconcileDone = false;
  if (typeof window !== 'undefined') {
    window.requestAnimationFrame(() => {
      reconcileOverlays();
      initialReconcileDone = true;
    });
  }

  // Re-measure on resize and post-update layout settle — neither emits a PM
  // tx. Shared rAF slot; the wider bound wins so we never miss an LCA.
  let resizeFrame: number | null = null;
  let pendingFirstChangedPos: number = Number.NEGATIVE_INFINITY;
  let pendingLastChangedPos: number = Number.POSITIVE_INFINITY;
  const schedulePostUpdateMeasure = (
    firstChangedPos: number,
    lastChangedPos: number = Number.POSITIVE_INFINITY
  ) => {
    if (!initialReconcileDone) {
      return;
    }
    if (resizeFrame === null) {
      pendingFirstChangedPos = firstChangedPos;
      pendingLastChangedPos = lastChangedPos;
      resizeFrame = window.requestAnimationFrame(() => {
        resizeFrame = null;
        reconcileOverlays(true, pendingFirstChangedPos, pendingLastChangedPos);
      });
    } else {
      pendingFirstChangedPos = Math.min(pendingFirstChangedPos, firstChangedPos);
      pendingLastChangedPos = Math.max(pendingLastChangedPos, lastChangedPos);
    }
  };
  // Width-only watch: intra-LCA wraps only change with content-box width.
  // Height-only changes (Enter, images settling) shift LCAs vertically and
  // CSS moves the SVG with them — measuring those would re-introduce
  // per-keystroke cost.
  let lastObservedClientWidth: number = typeof window !== 'undefined' ? view.dom.clientWidth : 0;
  const handleResize = () => {
    // ResizeObserver fires synchronously on `.observe()`.
    if (!initialReconcileDone) {
      return;
    }
    const currentWidth = view.dom.clientWidth;
    if (currentWidth === lastObservedClientWidth) {
      return;
    }
    lastObservedClientWidth = currentWidth;
    schedulePostUpdateMeasure(Number.NEGATIVE_INFINITY, Number.POSITIVE_INFINITY);
  };
  const resizeObserver =
    typeof ResizeObserver !== 'undefined' ? new ResizeObserver(handleResize) : null;
  resizeObserver?.observe(view.dom);

  return {
    update: (currentView: EditorView, prevState: EditorState) => {
      if (!shouldReconcileOverlays(currentView, prevState)) {
        return;
      }
      const docChanged = hasDocChanged(currentView, prevState);
      const { firstChangedPos, lastChangedPos } = getChangedDocRange(
        currentView,
        prevState,
        docChanged
      );
      reconcileOverlays(docChanged, firstChangedPos, lastChangedPos);
      // Catch-up rAF for layout that settles a tick after the sync DOM
      // mutation (web fonts, images, CSS transitions). ResizeObserver doesn't
      // fire for inner reflow.
      if (docChanged) {
        schedulePostUpdateMeasure(firstChangedPos, lastChangedPos);
      }
    },
    destroy: () => {
      resizeObserver?.disconnect();
      if (resizeFrame !== null) {
        window.cancelAnimationFrame(resizeFrame);
        resizeFrame = null;
      }
      containerResizeRegistry.destroy();
      for (const key of Array.from(overlays.keys())) {
        dropOverlay(key);
      }
    },
  };
};

export const createWidgetController = (view: EditorView, previewState: SketchPreviewState) => {
  const controller = createEditorRoughOverlayController(view, previewState);
  return {
    update: (currentView: EditorView, prevState: EditorState) =>
      controller.update(currentView, prevState),
    destroy: () => controller.destroy(),
  };
};
