import type { EditorPluginCreator } from './../ricos-types/index.js';

import { textColorConverter } from './color-converter.js';
import { getTextColorTextButtons } from './get-text-color-text-buttons.js';
import { tiptapColorForegroundExtension } from './tiptap-foreground.js';
import type { TextColorPluginEditorConfig } from './types.js';
import { TEXT_COLOR_TYPE } from './types.js';

export const pluginTextColor: EditorPluginCreator<TextColorPluginEditorConfig> = (
  config = {} as TextColorPluginEditorConfig
) => {
  return {
    config: { ...config, type: 'textColor' as const },
    pmMarkConverters: [textColorConverter],
    pmNodeConverters: [],
    type: TEXT_COLOR_TYPE,
    textButtons: getTextColorTextButtons(config),
    tiptapExtensions: [tiptapColorForegroundExtension],
  };
};
