import type { EditorState } from './../../tiptap/pm/state.js';
import { PluginKey } from './../../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';

import { TEXT_LAYER_Z_INDEX } from './defaults.js';
import {
  type PreviewOverride,
  type TrackedAnnotationGroup,
  buildSyntheticPreviewTrackedGroups,
  isOverlayPreviewStyle,
  isTrackedAnnotationGroupContainedInPreview,
} from './range-tracking.js';

export type SketchPluginState = {
  decorations: DecorationSet;
  trackedGroups: TrackedAnnotationGroup[];
  nextRangeId: number;
};

export const SKETCH_PLUGIN_KEY = new PluginKey<SketchPluginState>('sketchDecorations');

export const WIDGET_DATA_HOOK = 'sketch-widget';
export const WIDGET_KEY_ATTR = 'data-rn-key';

const widgetDomFactory = (key: string) => () => {
  const div = document.createElement('div');
  div.setAttribute('data-hook', WIDGET_DATA_HOOK);
  div.setAttribute(WIDGET_KEY_ATTR, key);
  div.style.cssText =
    'position: absolute; pointer-events: none; left: 0; top: 0; width: 0; height: 0;';
  return div;
};

// Widget anchor only. The host's `position: relative` is supplied by a global
// `:has(> [data-hook="sketch-widget"])` rule (in
// `overlay-handle.ts`); a `Decoration.node` for that was measurable
// per-keystroke cost in `DecorationSet.forChild`.
const pushDecorationsForTrackedGroup = (
  decorations: Decoration[],
  trackedGroup: TrackedAnnotationGroup
) => {
  decorations.push(
    Decoration.widget(trackedGroup.lcaStart, widgetDomFactory(trackedGroup.id), {
      side: -1,
      key: trackedGroup.id,
      marks: [],
    })
  );
};

export const buildDecorationSet = (
  state: EditorState,
  trackedGroups: TrackedAnnotationGroup[],
  previewOverride: PreviewOverride | null
): DecorationSet => {
  const decorations: Decoration[] = [];

  for (const trackedGroup of trackedGroups) {
    // Preview owns the visual representation while active.
    if (
      previewOverride &&
      isTrackedAnnotationGroupContainedInPreview(trackedGroup, previewOverride)
    ) {
      continue;
    }
    pushDecorationsForTrackedGroup(decorations, trackedGroup);
  }

  if (previewOverride) {
    if (isOverlayPreviewStyle(previewOverride.style)) {
      // One widget per synthetic group (per textblock for stroke styles).
      for (const synthetic of buildSyntheticPreviewTrackedGroups(state, previewOverride)) {
        pushDecorationsForTrackedGroup(decorations, synthetic);
      }
    }
    // Mirror what `renderHTML` produces for a real mark: lift text above the
    // HIGHLIGHT overlay. Skipped for CLASSIC — text-color's `previewHighlight`
    // paints the new bg and the `!important` mask would override it. Parent
    // COLOR_BACKGROUND marks are hidden by the preview transaction so partial
    // previews only clear the selected subset, not the entire parent span.
    if (previewOverride.style !== 'CLASSIC') {
      decorations.push(
        Decoration.inline(previewOverride.from, previewOverride.to, {
          style: `background-color: transparent !important; position: relative; z-index: ${TEXT_LAYER_Z_INDEX};`,
        })
      );
    }
  }

  return DecorationSet.create(state.doc, decorations);
};

export const getPluginState = (state: EditorState): SketchPluginState | undefined =>
  SKETCH_PLUGIN_KEY.getState(state);
