import type { PmMarkConverter } from './../../pm-converters/types.js';
import type { SketchDecoration } from './../../ricos-schema/next-schema/index.js';
import { Decoration_Type, SketchData_Variant } from './../../ricos-schema/next-schema/index.js';
import { Mark_Type } from './../../ricos-types/index.js';

import { DEFAULT_STYLE, getExplicitAnimate } from './defaults.js';

const KNOWN_STYLES = new Set<string>(Object.values(SketchData_Variant));
const isStyle = (value: unknown): value is SketchData_Variant =>
  typeof value === 'string' && KNOWN_STYLES.has(value);

export const sketchConverter: PmMarkConverter = {
  fromPm: {
    type: Mark_Type.SKETCH,
    convert: mark => {
      const style: SketchData_Variant = isStyle(mark.attrs?.style)
        ? mark.attrs?.style
        : (DEFAULT_STYLE as SketchData_Variant);
      const color = mark.attrs?.color;
      const animate = getExplicitAnimate(mark.attrs?.animate);
      return [
        {
          type: Decoration_Type.SKETCH,
          sketchData: {
            variant: style,
            ...(typeof color === 'string' && { color }),
            ...(animate !== undefined && { animate }),
          },
        },
      ];
    },
  },
  toPm: {
    type: Decoration_Type.SKETCH,
    convert: decoration => {
      const { sketchData } = decoration as SketchDecoration;
      if (!sketchData) {
        return undefined;
      }
      const { variant, color } = sketchData;
      const animate = getExplicitAnimate(sketchData.animate);
      return {
        type: Mark_Type.SKETCH,
        attrs: {
          style: variant,
          ...(typeof color === 'string' && { color }),
          ...(animate !== undefined && { animate }),
        },
      };
    },
  },
};
