import React, { useEffect, useState } from 'react';

import { Decoration_Type, type Node as RicosNode } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { NodeViewDecorator } from './../ricos-types/index.js';

type DecorateArgs = Parameters<NodeViewDecorator<JSX.Element>['decorate']>[0];

let sketchDecorator: NodeViewDecorator<JSX.Element> | null = null;
let sketchDecoratorPromise: Promise<NodeViewDecorator<JSX.Element>> | null = null;

const loadSketchDecorator = () => {
  if (sketchDecorator) {
    return Promise.resolve(sketchDecorator);
  }
  sketchDecoratorPromise ??= import(
    /* webpackChunkName: "ricos_plugin_sketch_viewer_decorator" */ './sketch/node-view-decorator.js'
  ).then(mod => {
    sketchDecorator = mod.SketchDecorator;
    return sketchDecorator;
  });
  return sketchDecoratorPromise;
};

const hasSketchDecoration = (node: RicosNode) =>
  !!node.textData?.decorations?.some(({ type }) => type === Decoration_Type.SKETCH);

const SketchDecoratorLoader = (args: DecorateArgs) => {
  const [decorator, setDecorator] = useState(sketchDecorator);

  useEffect(() => {
    let mounted = true;
    void loadSketchDecorator().then(loadedDecorator => {
      if (mounted) {
        setDecorator(loadedDecorator);
      }
    });
    return () => {
      mounted = false;
    };
  }, []);

  if (!decorator) {
    return <>{args.element}</>;
  }

  return decorator.decorate(args);
};

export const sketchNodeViewDecorator: NodeViewDecorator<JSX.Element> = {
  rule: hasSketchDecoration,
  decorate: args => <SketchDecoratorLoader {...args} />,
};
