import { TextColor } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import type { ModalService } from './../ricos-modals/modal-service.js';
import type { Modal, TextButton } from './../ricos-types/index.js';
import { Decoration_Type } from './../ricos-types/index.js';
import { getTextColorInSelection } from './../_shared/resolvers/get-text-color-in-selection.js';
import { isAlwaysVisible } from './../_shared/resolvers/is-always-visible.js';
import { isNodeSelected } from './../_shared/resolvers/is-node-selected.js';
import { ColorPickerButton } from './../toolbars-v3/components/buttons/TextColorButton/text-color-button.js';

import { TEXT_COLOR_MODAL_ID } from './constants.js';
import { TEXT_BUTTON_TEXT_COLOR } from './data-hooks.js';
import classes from './text-button-color-scss.js';
import { TextColorPicker } from './text-color-picker.js';
import type { TextColorPluginEditorConfig, TextHighlightPluginEditorConfig } from './types.js';

export const getTextColorTextButtons = (
  config: TextColorPluginEditorConfig = { type: 'textColor' }
): TextButton[] => {
  return [
    {
      id: `${Decoration_Type.COLOR}.foreground`,
      type: 'modal',
      presentation: {
        dataHook: TEXT_BUTTON_TEXT_COLOR,
        tooltip: 'TextColorButton_Tooltip',
        getIcon({ publicCommands }) {
          const color = publicCommands.getColor('ricos-text-color');
          return () => (
            <TextColor
              className={classes.textColorIcon}
              style={{ '--ricos-internal-text-color': color } as React.CSSProperties}
            />
          );
        },
        renderer: toolbarItem => (
          <ColorPickerButton toolbarItem={toolbarItem} modalId={TEXT_COLOR_MODAL_ID} />
        ),
      },
      attributes: {
        visible: isAlwaysVisible,
        selectedTextColor: getTextColorInSelection,
        disabled: isNodeSelected,
      },
      command:
        ({ referenceElement, modalService }) =>
        () => {
          modalService.isModalOpen(TEXT_COLOR_MODAL_ID)
            ? modalService.closeModal(TEXT_COLOR_MODAL_ID)
            : openColorModal({
                modalId: TEXT_COLOR_MODAL_ID,
                modalType: 'ricos-text-color',
                modalService,
                config,
                referenceElement,
              });
          return true;
        },
    },
  ];
};

export const openColorModal = ({
  modalId,
  modalType,
  modalService,
  referenceElement,
  config,
}: {
  modalId: string;
  modalService: ModalService;
  onClickOutside?: Modal['onClickOutside'];
  referenceElement?: HTMLElement | null;
  modalType: 'ricos-text-color' | 'ricos-text-highlight';
  config: TextColorPluginEditorConfig | TextHighlightPluginEditorConfig;
}) => {
  modalService.openModal({
    id: modalId,
    Component: TextColorPicker,
    componentProps: {
      referenceElement: referenceElement as HTMLDivElement,
      type: modalType,
      config,
    },
    layout: {
      desktop: referenceElement ? 'floating' : 'dialog',
      mobile: 'drawer',
    },
    noPadding: true,
    ...(referenceElement && {
      positioning: { placement: 'bottom', referenceElement },
    }),
    onClickOutside: {
      on: 'pointerup',
      handler: () => {},
    },
    returnFocusToEditor: true,
    disableArrowNavigation: true,
    dragHandleSelector: '[data-drag-handler]',
    enableDrag: true,
    withTransition: true,
  });
};
