import type { EditorView } from './../../tiptap/pm/view.js';

import type { AnnotationRange } from './range-tracking.js';
import { getOverlayRects } from './rect-utils.js';

// With side: -1, `domAtPos(to)` lands past a trailing widget; its 0×0 div
// (pinned to the editor root) contributes a (0,0,0,0) rect that would
// stretch e.g. CIRCLE bounds to the editor's top-left. Real text rects
// always have non-zero w *and* h.
//
// We keep the single-Range `domAtPos` traversal (vs per-text-node
// `nodesBetween` + `view.nodeDOM`) because preview inline decorations split
// PM text nodes — a per-text-node loop hits IndexSizeError on `setEnd`.
const isNonEmptyRect = (rect: DOMRect): boolean => rect.width > 0 || rect.height > 0;

export const collectRangeRects = (view: EditorView, from: number, to: number): DOMRect[] | null => {
  try {
    const start = view.domAtPos(from, 1);
    const end = view.domAtPos(to, -1);
    const range = document.createRange();
    range.setStart(start.node, start.offset);
    range.setEnd(end.node, end.offset);
    return Array.from(range.getClientRects()).filter(isNonEmptyRect);
  } catch {
    return null;
  }
};

export const buildRangesRects = (
  view: EditorView,
  ranges: AnnotationRange[],
  style: string
): DOMRect[] | null => {
  const rects: DOMRect[] = [];
  for (const range of ranges) {
    const rangeRects = collectRangeRects(view, range.from, range.to);
    if (!rangeRects) {
      return null;
    }
    rects.push(...rangeRects);
  }
  if (rects.length === 0) {
    return null;
  }
  return getOverlayRects(style, rects);
};
